import math
import hashlib
from typing import Hashable


class CountMinSketch:
    """Count-Min Sketch for approximate frequency estimation."""

    def __init__(self, width: int = 2048, depth: int = 5):
        self.width = width
        self.depth = depth
        self.table = [[0] * width for _ in range(depth)]

    def _hashes(self, item: Hashable):
        raw = str(item).encode()
        h1 = int.from_bytes(hashlib.md5(raw).digest(), "big")
        h2 = int.from_bytes(hashlib.sha1(raw).digest(), "big")
        for i in range(self.depth):
            yield (h1 + i * h2) % self.width

    def add(self, item: Hashable, count: int = 1):
        """Increment the frequency estimate for item by count. O(1)."""
        for row, col in enumerate(self._hashes(item)):
            self.table[row][col] += count

    def estimate(self, item: Hashable) -> int:
        """Return the estimated frequency of item (never underestimates)."""
        return min(self.table[row][col] for row, col in enumerate(self._hashes(item)))

    @classmethod
    def from_error_rate(cls, epsilon: float = 0.001, delta: float = 0.01):
        """Create a sketch with width=ceil(e/epsilon) and depth=ceil(ln(1/delta))."""
        return cls(width=math.ceil(math.e / epsilon), depth=math.ceil(math.log(1 / delta)))
